CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS kb_dataset (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, description VARCHAR(1000), embedding_model VARCHAR(100) NOT NULL DEFAULT 'bge-large-zh-v1.5', llm_model VARCHAR(100) NOT NULL DEFAULT 'mock', rerank_model VARCHAR(100) NOT NULL DEFAULT 'mock', chunk_size INT NOT NULL DEFAULT 512, chunk_overlap INT NOT NULL DEFAULT 64, top_k INT NOT NULL DEFAULT 5, similarity_threshold DECIMAL(3,2) NOT NULL DEFAULT .70, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', create_time TIMESTAMP NOT NULL DEFAULT NOW(), update_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_document (id BIGSERIAL PRIMARY KEY, dataset_id BIGINT NOT NULL REFERENCES kb_dataset(id), file_name VARCHAR(500) NOT NULL, file_type VARCHAR(20) NOT NULL, file_size BIGINT, file_hash VARCHAR(64), index_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', error_msg TEXT, chunk_count INT DEFAULT 0, token_count INT DEFAULT 0, version INT NOT NULL DEFAULT 1, create_time TIMESTAMP NOT NULL DEFAULT NOW(), update_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_chunk (id BIGSERIAL PRIMARY KEY, document_id BIGINT NOT NULL REFERENCES kb_document(id), dataset_id BIGINT NOT NULL REFERENCES kb_dataset(id), chunk_index INT NOT NULL, content TEXT NOT NULL, embedding vector(1024), metadata JSONB DEFAULT '{}', version INT NOT NULL DEFAULT 1, create_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_index_outbox (id BIGSERIAL PRIMARY KEY, event_type VARCHAR(30) NOT NULL, dataset_id BIGINT NOT NULL, document_id BIGINT, chunk_id BIGINT, payload JSONB DEFAULT '{}', status VARCHAR(20) NOT NULL DEFAULT 'PENDING', retry_count INT DEFAULT 0, error_msg TEXT, create_time TIMESTAMP NOT NULL DEFAULT NOW(), update_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_retrieval_trace (id BIGSERIAL PRIMARY KEY, dataset_id BIGINT NOT NULL, query_original TEXT NOT NULL, vector_results JSONB DEFAULT '[]', bm25_results JSONB DEFAULT '[]', fused_results JSONB DEFAULT '[]', rerank_results JSONB DEFAULT '[]', context_chunks JSONB DEFAULT '[]', confidence DECIMAL(3,2), refused BOOLEAN DEFAULT FALSE, latency_ms INT, create_time TIMESTAMP NOT NULL DEFAULT NOW());
